SET NAMES utf8mb4;
INSERT INTO nb_card_text
(card_id,audience_code,language_code,content_version,title,subtitle,reflection_keywords,
 what_do_you_see,card_room,helpful_side,difficult_side,context_questions_json,
 own_card_language,possible_next_step,status_code)
VALUES
('major-00','CHILD','de','0.1.0','Der Narr','Ein kleiner Schritt ins Neue',NULL,'Schau dir die Karte erst einmal ganz in Ruhe an. Was entdeckst du zuerst? Was wirkt spannend, lustig, seltsam oder vielleicht ein bisschen unsicher?','Der Narr steht am Anfang eines Weges, den er noch nicht kennt. Vielleicht hat er Lust loszugehen. Vielleicht weiß er auch noch gar nicht, was kommt. Diese Karte kann dich daran erinnern: Du musst nicht schon alles wissen, bevor du etwas Neues ausprobierst.','Neugier kann dir helfen, einen ersten Schritt zu machen. Du darfst ausprobieren, fragen, umkehren oder deine Meinung ändern.','Etwas Neues kann auch zu viel oder zu unübersichtlich sein. Mut bedeutet nicht, dass du ohne Hilfe losgehen musst. Mehr Informationen, Zeit oder Begleitung können den Weg sicherer machen.','["Gibt es etwas, das du gern ausprobieren möchtest?", "Was würde dir helfen, dich dabei sicherer zu fühlen?", "Möchtest du wirklich losgehen – oder denken andere, dass du es solltest?"]','Was bedeutet „etwas Neues ausprobieren“ heute für dich?','Du könntest dir nur den allerersten kleinen Schritt anschauen. Mehr musst du heute noch nicht entscheiden.','draft-review'),
('major-01','CHILD','de','0.1.0','Der Magier','Entdecken, was du schon kannst',NULL,'Was fällt dir auf? Welche Dinge, Werkzeuge oder Zeichen siehst du? Was davon würdest du gern genauer anschauen?','Vor dem Magier liegen verschiedene Dinge, die er benutzen kann. Die Karte kann dich fragen: Was kannst du schon? Was weißt du? Wer oder was kann dir helfen?','Manchmal ist schon vieles da, was du für eine Idee brauchst: Wissen, Fantasie, Übung, ein Werkzeug oder ein Mensch, den du fragen kannst.','Du musst nicht alles allein können. Auch wenn du etwas gut kannst, musst du es nicht immer benutzen. Und niemand muss perfekt sein, bevor etwas beginnen darf.','["Was kannst du schon, das dir heute helfen könnte?", "Welches Werkzeug oder welche Hilfe wäre praktisch?", "Wen könntest du um Unterstützung bitten?"]','Wann fühlst du dich wirksam – also so, als könntest du wirklich etwas verändern?','Wähle eine Sache aus, die dir schon zur Verfügung steht, und probiere damit etwas Kleines.','draft-review'),
('major-02','CHILD','de','0.1.0','Die Hohepriesterin','Hören, was leise ist',NULL,'Was wirkt auf dieser Karte still oder geheimnisvoll? Gibt es etwas, das du erst beim zweiten Hinsehen bemerkst?','Die Hohepriesterin erinnert an Dinge, die wir manchmal spüren, bevor wir sie erklären können. Vielleicht fühlt sich etwas gut, komisch, ruhig oder unpassend an, obwohl du noch nicht weißt, warum.','Ruhe und genaues Beobachten können helfen, feine Signale wahrzunehmen. Du darfst etwas erst einmal bemerken, ohne sofort eine Antwort zu brauchen.','Ein Gefühl kann wichtig sein, aber es weiß nicht immer alles. Manchmal hilft es, zusätzlich nachzufragen, Informationen zu sammeln oder mit jemandem zu sprechen.','["Gibt es etwas, das du gerade spürst, aber noch nicht erklären kannst?", "Brauchst du eher Ruhe oder jemanden zum Reden?", "Was möchtest du erst einmal nur beobachten?"]','Wie fühlt sich deine innere Stimme heute an?','Du könntest eine Beobachtung aufschreiben oder malen, ohne gleich entscheiden zu müssen, was sie bedeutet.','draft-review'),
('major-03','CHILD','de','0.1.0','Die Kaiserin','Was wachsen darf',NULL,'Was wirkt lebendig, warm oder gemütlich? Was scheint auf dieser Karte gut versorgt zu sein?','Die Kaiserin steht für Wachsen, Versorgen, Gestalten und Genießen. Sie kann fragen: Was braucht gerade Aufmerksamkeit, Nahrung, Ruhe oder Zeit?','Dinge können leichter wachsen, wenn ihre Bedürfnisse gesehen werden. Das gilt für Pflanzen, Ideen, Freundschaften – und auch für dich.','Sich kümmern kann anstrengend werden, besonders wenn du immer nur für andere da bist. Auch zu viel von etwas Schönem kann irgendwann zu viel sein.','["Was braucht heute ein bisschen Pflege?", "Was tut dir gut?", "Wo darfst du selbst etwas bekommen, statt nur zu geben?"]','Was bedeutet Fürsorge für dich?','Du könntest heute eine kleine Sache tun, die dir oder etwas Wichtigem gut tut.','draft-review'),
('major-04','CHILD','de','0.1.0','Der Kaiser','Struktur, die Sicherheit geben kann',NULL,'Was wirkt fest, geordnet oder stark? Gibt es etwas, das dir Sicherheit vermittelt?','Der Kaiser steht für Regeln, Grenzen und Verantwortung. Manche Strukturen helfen uns zu wissen, was passiert und wer für was zuständig ist.','Klare Regeln und Abläufe können beruhigen. Eine gute Grenze kann schützen und es leichter machen, zu handeln.','Regeln passen nicht immer zu jeder Situation. Eine Struktur soll Menschen helfen – nicht Menschen zwingen, in eine Struktur zu passen.','["Welche Regel hilft dir gerade?", "Wo brauchst du eine klarere Grenze?", "Gibt es eine Regel, die nicht mehr gut passt?"]','Welche Art von Ordnung fühlt sich für dich sicher an?','Du könntest eine einzige Regel oder Grenze benennen, die dir heute helfen würde.','draft-review'),
('major-05','CHILD','de','0.1.0','Der Hierophant','Prüfen, was andere dir zeigen',NULL,'Was sieht auf der Karte nach Wissen, Lernen oder Tradition aus? Wer scheint etwas zu erklären oder weiterzugeben?','Der Hierophant steht für Wissen, Regeln und Dinge, die Menschen schon lange miteinander teilen. Du darfst von anderen lernen – und trotzdem prüfen, ob etwas zu dir passt.','Erfahrungen anderer können hilfreich sein. Du musst nicht alles selbst herausfinden, wenn jemand etwas schon gut erklären kann.','Nur weil viele Menschen etwas so machen, muss es nicht für alle richtig sein. Manche Regeln dürfen verändert werden.','["Von wem lernst du gern?", "Welche Regel hilft dir?", "Welche Regel würdest du gern genauer prüfen?"]','Was möchtest du behalten – und was möchtest du anders machen?','Nimm eine Regel und frage: Wem hilft sie eigentlich, und passt sie gerade noch?','draft-review'),
('major-06','CHILD','de','0.1.0','Die Liebenden','Verbunden sein und trotzdem du bleiben',NULL,'Welche Wesen, Menschen oder Dinge scheinen miteinander verbunden zu sein? Was fühlt sich nah oder freundlich an?','Die Liebenden stehen für Verbindung und wichtige Entscheidungen. Dabei kann es um Freundschaft, Familie, Zusammenarbeit oder die Beziehung zu dir selbst gehen.','Eine gute Verbindung kann sich sicher und echt anfühlen. Unterschiede dürfen trotzdem bleiben.','Nähe ist nicht gut, wenn du dabei deine eigenen Bedürfnisse oder Grenzen vergessen musst. Du darfst auch in einer Verbindung Nein sagen.','["Mit wem fühlst du dich verbunden?", "Was ist dir in einer Freundschaft oder Beziehung wichtig?", "Kannst du du selbst bleiben, wenn du mit jemandem zusammen bist?"]','Wie fühlt sich eine gute Verbindung für dich an?','Du könntest einer Person sagen, was dir in eurer Verbindung wichtig ist.','draft-review'),
('major-07','CHILD','de','0.1.0','Der Wagen','Deine Richtung finden',NULL,'Wo scheint es auf der Karte hinzugehen? Wirkt die Bewegung schnell, ruhig, schwierig oder klar?','Der Wagen steht für Bewegung und Richtung. Manchmal ziehen verschiedene Wünsche gleichzeitig an uns. Dann kann es helfen zu überlegen: Wohin möchte ich eigentlich?','Eine Richtung kann dir helfen, deine Kraft nicht überall gleichzeitig einzusetzen. Du musst dafür nicht schnell sein.','Wenn du nur noch vorwärts willst, kannst du übersehen, dass du müde bist oder eine Pause brauchst. Tempo und Richtung sind zwei verschiedene Dinge.','["Wohin möchtest du gerade?", "Was zieht dich in verschiedene Richtungen?", "Welches Tempo passt heute zu dir?"]','Woran merkst du, dass eine Richtung wirklich deine ist?','Entscheide zuerst nur die Richtung. Wie schnell du gehst, kannst du später bestimmen.','draft-review'),
('major-08','CHILD','de','0.1.0','Die Kraft','Stark sein kann auch sanft sein',NULL,'Was wirkt stark? Was wirkt gleichzeitig ruhig oder vorsichtig?','Die Kraft erinnert daran, dass Stärke nicht nur laut, schnell oder mutig aussehen muss. Stark kann auch sein: ruhig bleiben, Hilfe holen, eine Pause machen oder eine Grenze schützen.','Gefühle müssen nicht weggedrückt werden. Wenn du verstehst, was in dir passiert, kannst du oft besser damit umgehen.','Du musst nicht alles aushalten, um stark zu sein. Immer weiterzumachen kann Kraft kosten, statt Kraft zu zeigen.','["Welche Kraft spürst du gerade?", "Braucht sie Bewegung, Ruhe oder Schutz?", "Wo wäre freundlich mit dir sein hilfreicher als Druck?"]','Was bedeutet Stärke für dich?','Du könntest heute deine Kraft so einsetzen, dass noch etwas davon für später übrig bleibt.','draft-review'),
('major-09','CHILD','de','0.1.0','Der Eremit','Ein eigener ruhiger Raum',NULL,'Was wirkt still oder weit weg? Wo ist Licht? Wie fühlt sich das Alleinsein auf der Karte an?','Der Eremit zieht sich für eine Weile zurück. Alleinsein kann helfen, wenn es zu laut, zu voll oder zu anstrengend geworden ist.','Ein eigener Raum kann dir helfen, Gedanken und Gefühle wieder besser zu hören. Du darfst gern allein sein.','Alleinsein ist etwas anderes als sich allein gelassen fühlen. Wenn du eigentlich Nähe brauchst, darf Hilfe erreichbar bleiben.','["Möchtest du gerade lieber allein sein oder mit jemandem zusammen?", "Was wird leichter, wenn es ruhiger ist?", "Wer darf trotzdem erreichbar bleiben?"]','Was findest du leichter heraus, wenn es stiller wird?','Schaffe dir einen kleinen ruhigen Raum und entscheide selbst, wann du wieder herauskommen möchtest.','draft-review'),
('major-10','CHILD','de','0.1.0','Das Rad des Schicksals','Dinge verändern sich',NULL,'Was bewegt sich auf der Karte? Was könnte sich drehen, wiederholen oder verändern?','Das Rad erinnert daran, dass nicht alles immer gleich bleibt. Manche Veränderungen machen wir selbst. Andere passieren, weil Zeit vergeht oder sich etwas um uns herum verändert.','Ein schwieriger Moment ist nicht für immer. Veränderungen können neue Möglichkeiten bringen.','Es kann unangenehm sein, wenn sich etwas verändert, das du gern gleich behalten möchtest. Und nicht jede Veränderung muss sofort einen Sinn haben.','["Was verändert sich gerade?", "Was kannst du beeinflussen?", "Was kannst du gerade nicht bestimmen?"]','Wie fühlt sich Veränderung für dich heute an?','Trenne eine Sache, die du beeinflussen kannst, von einer Sache, die du gerade nur beobachten kannst.','draft-review'),
('major-11','CHILD','de','0.1.0','Die Gerechtigkeit','Was ist wirklich fair?',NULL,'Was sieht auf der Karte nach Abwägen, Entscheiden oder Vergleichen aus?','Die Gerechtigkeit fragt nicht nur: Bekommen alle genau dasselbe? Sie fragt auch: Was braucht jemand, damit es wirklich fair wird?','Klare und erklärbare Entscheidungen können Sicherheit schaffen. Fair kann bedeuten, dass unterschiedliche Menschen unterschiedliche Hilfe bekommen.','Eine Regel kann unfair wirken, wenn wichtige Unterschiede vergessen werden. Auch mit dir selbst kannst du zu streng sein.','["Was wäre hier fair?", "Fehlt noch eine wichtige Information?", "Bist du zu dir genauso fair wie zu anderen?"]','Was bedeutet Fairness in dieser Situation für dich?','Schau dir die Situation aus zwei verschiedenen Blickwinkeln an, bevor du entscheidest.','draft-review'),
('major-12','CHILD','de','0.1.0','Der Gehängte','Ein anderer Blick',NULL,'Was ist auf dieser Karte andersherum oder ungewöhnlich? Wie verändert das deinen Blick?','Der Gehängte zeigt einen Moment, in dem Weiterkämpfen vielleicht nicht hilft. Manchmal sieht man etwas Neues, wenn man kurz aufhört, es sofort lösen zu wollen.','Eine Pause kann eine echte Entscheidung sein. Dein Gehirn darf Zeit bekommen, etwas anders zu sortieren.','Warten ist schwer, wenn du gar keine Wahl hast. Eine Pause bedeutet auch nicht, dass du Hilfe oder eine wichtige Veränderung aufgeben musst.','["Was sieht anders aus, wenn du es aus einer anderen Richtung anschaust?", "Ist deine Pause freiwillig?", "Was darf kurz ruhen?"]','Wie fühlt es sich für dich an, etwas gerade nicht lösen zu müssen?','Du könntest eine Sache bewusst auf später verschieben und festlegen, wann du wieder hinschaust.','draft-review'),
('major-13','CHILD','de','0.1.0','Der Tod','Etwas endet, etwas verändert sich',NULL,'Was wirkt auf der Karte wie Abschied oder Veränderung? Gibt es auch etwas, das nach Neubeginn aussieht?','Der Name dieser Karte klingt erst einmal groß oder vielleicht gruselig. Im Tarot geht es hier normalerweise nicht darum, dass jemand stirbt. Die Karte steht für Dinge, die enden oder sich so stark verändern, dass etwas Neues entstehen kann.','Du darfst merken: Etwas ist vorbei. Ein Ende löscht nicht, was vorher wichtig war. Es kann aber Platz für einen neuen Abschnitt schaffen.','Abschiede können traurig, wütend oder verwirrend machen. Du musst nicht sofort bereit für etwas Neues sein.','["Was verändert sich gerade?", "Was möchtest du von vorher behalten?", "Was braucht Zeit, bevor etwas Neues beginnen kann?"]','Was bedeutet Abschied oder Veränderung für dich?','Du könntest eine Sache benennen, die vorbei ist, und eine Sache, die du davon mitnehmen möchtest.','draft-review'),
('major-14','CHILD','de','0.1.0','Die Mäßigkeit','Die passende Mischung finden',NULL,'Was wird auf der Karte gemischt oder verbunden? Wirkt es ruhig, genau oder vorsichtig?','Die Mäßigkeit fragt nach der passenden Menge. Nicht immer braucht man mehr oder weniger von allem – manchmal braucht man genau die Mischung, die heute passt.','Du darfst Dinge ausprobieren und neu dosieren: Aktivität und Pause, Nähe und Alleinsein, Laut und Leise.','Du musst nicht immer perfekt ausgeglichen sein. Manchmal brauchst du keine Mitte, sondern ganz klar mehr Schutz oder eine Grenze.','["Wovon brauchst du heute mehr?", "Wovon brauchst du weniger?", "Brauchst du Balance oder eher Schutz?"]','Wie sieht deine passende Mischung heute aus?','Verändere nur eine kleine Menge: ein bisschen mehr von etwas Hilfreichem oder ein bisschen weniger von etwas Anstrengendem.','draft-review'),
('major-15','CHILD','de','0.1.0','Der Teufel','Muster entdecken, die festhalten',NULL,'Was wirkt auf der Karte anziehend, festgebunden oder schwer loszulassen?','Der Teufel kann Dinge zeigen, die uns festhalten: Gewohnheiten, Erwartungen, Ängste oder etwas, das sich gleichzeitig gut und schwierig anfühlt.','Wenn du ein Muster bemerkst, hast du mehr Möglichkeiten, damit umzugehen. Manche Gewohnheiten haben einmal geholfen, auch wenn sie heute nicht mehr so gut passen.','Du bist nicht schuld, nur weil etwas schwer zu verändern ist. Manche Situationen brauchen Unterstützung und sichere Alternativen.','["Was gibt dir dieses Muster?", "Was macht es schwieriger?", "Welche kleine andere Möglichkeit wäre sicher genug zum Ausprobieren?"]','Wo möchtest du mehr auswählen können?','Beobachte das Muster erst einmal, ohne von dir zu verlangen, es sofort zu verändern.','draft-review'),
('major-16','CHILD','de','0.1.0','Der Turm','Wenn etwas plötzlich nicht mehr hält',NULL,'Was passiert auf der Karte? Was wirkt unsicher? Was könnte jetzt Schutz brauchen?','Der Turm zeigt einen Moment, in dem etwas, das sicher wirkte, plötzlich wackelt oder zusammenbricht. Das kann eine Idee, ein Plan oder eine Situation sein.','Wenn etwas nicht mehr trägt, kann sichtbar werden, was wirklich gebraucht wird. Später kann etwas Passenderes aufgebaut werden.','Plötzliche Veränderungen können Angst machen. Dann muss nicht sofort nach einer Bedeutung gesucht werden. Sicherheit und Hilfe sind zuerst wichtig.','["Was fühlt sich gerade unsicher an?", "Was würde dir jetzt Stabilität geben?", "Was muss heute noch gar nicht neu aufgebaut werden?"]','Was möchtest du schützen, auch wenn sich etwas verändert?','Kümmere dich zuerst um Sicherheit. Was danach kommt, darf später entschieden werden.','draft-review'),
('major-17','CHILD','de','0.1.0','Der Stern','Ein kleines Licht behalten',NULL,'Wo siehst du Licht? Was wirkt ruhig, hoffnungsvoll oder weit?','Der Stern kann wie ein kleines Licht nach einer schwierigen Zeit sein. Er verspricht nicht, dass alles sofort gut wird. Er erinnert daran, dass es trotzdem etwas geben kann, das dich weiterträgt.','Hoffnung darf klein sein. Vielleicht ist es ein Mensch, ein Ort, eine Idee oder etwas, auf das du dich freust.','Du musst nicht schnell wieder fröhlich sein. Erholen braucht bei jedem Menschen unterschiedlich viel Zeit.','["Was macht dir ein kleines bisschen Hoffnung?", "Wo kannst du einfach du sein?", "Was hilft dir beim Erholen?"]','Welches kleine Licht möchtest du heute nicht übersehen?','Suche eine kleine Sache auf, die dir Ruhe, Hoffnung oder Kraft gibt.','draft-review'),
('major-18','CHILD','de','0.1.0','Der Mond','Wenn noch nicht alles klar ist',NULL,'Was sieht im Mondlicht anders aus? Was ist deutlich und was bleibt im Schatten?','Der Mond zeigt eine Welt, in der nicht alles klar zu erkennen ist. Gefühle, Erinnerungen und Fantasie können dann besonders stark sein.','Du darfst etwas fühlen, auch wenn du es noch nicht erklären kannst. Fantasie und feine Wahrnehmung können dir wichtige Hinweise geben.','Wenn vieles unklar ist, kann dein Kopf Lücken mit Sorgen füllen. Dann helfen manchmal Licht, Informationen, Zeit oder ein vertrauter Mensch.','["Was ist gerade noch unklar?", "Was weißt du wirklich – und was vermutest du nur?", "Was würde dir helfen, dich sicherer zu fühlen?"]','Wie gehst du damit um, wenn du etwas noch nicht weißt?','Du könntest eine Sache als „weiß ich“ und eine andere als „weiß ich noch nicht“ benennen.','draft-review'),
('major-19','CHILD','de','0.1.0','Die Sonne','Freude darf sichtbar sein',NULL,'Was wirkt hell, warm oder lebendig? Was macht dir beim Anschauen Freude?','Die Sonne steht für Lebendigkeit, Sichtbarkeit und Freude. Sie kann fragen, was in dir gerade Platz haben möchte, ohne sich dafür entschuldigen zu müssen.','Freude, Spiel und Stolz können Kraft geben. Du darfst etwas mögen, einfach weil du es magst.','Nicht jeder Tag fühlt sich sonnig an. Du musst nicht fröhlich wirken, wenn du es nicht bist. Und sichtbar sein ist nur dann schön, wenn es sich sicher anfühlt.','["Was macht dir gerade Freude?", "Was möchtest du zeigen?", "Wo möchtest du lieber für dich bleiben?"]','Was darf heute einfach schön sein?','Mach für einen kleinen Moment Platz für etwas, das dir wirklich Freude macht.','draft-review'),
('major-20','CHILD','de','0.1.0','Das Gericht','Etwas neu erkennen',NULL,'Was scheint auf der Karte zu rufen, zu wecken oder Aufmerksamkeit zu bekommen?','Das Gericht kann einen Moment zeigen, in dem du etwas plötzlich anders verstehst. Vielleicht merkst du: So möchte ich es weiter machen – oder genau so nicht mehr.','Neue Erkenntnisse können dir helfen, eine Entscheidung bewusster zu treffen. Du darfst aus Erfahrungen lernen, ohne dich dafür zu verurteilen.','Eine Erkenntnis muss nicht sofort zu einer großen Veränderung führen. Und du musst dich nicht bestrafen, weil du früher etwas noch nicht wusstest.','["Was verstehst du heute anders als früher?", "Was möchtest du damit machen?", "Was darf trotzdem noch Zeit brauchen?"]','Welche Erkenntnis ist gerade wichtig für dich?','Schreibe oder sage einen Satz: „Heute weiß ich …“ – ohne daraus sofort eine große Aufgabe zu machen.','draft-review'),
('major-21','CHILD','de','0.1.0','Die Welt','Etwas darf vollständig sein',NULL,'Was wirkt rund, verbunden oder abgeschlossen? Wo scheint alles zusammenzukommen?','Die Welt steht für Ankommen und Vollständigkeit. Nicht alles muss perfekt sein, damit etwas fertig oder wichtig genug sein darf.','Du darfst sehen, was du geschafft, gelernt oder erlebt hast. Ein Abschluss kann dir helfen, einen Abschnitt wirklich zu würdigen.','Fertigwerden kann sich auch komisch anfühlen. Vielleicht fehlt plötzlich etwas, woran du lange gearbeitet hast. Ein Abschluss darf gleichzeitig schön und traurig sein.','["Was hast du geschafft oder beendet?", "Was möchtest du davon mitnehmen?", "Was darf jetzt einfach fertig sein, ohne noch verbessert zu werden?"]','Woran merkst du, dass etwas für dich vollständig ist?','Halte kurz fest, was zu diesem Abschnitt gehört und was du daraus mitnehmen möchtest.','draft-review')
